const HTTP_STATUS_CODES = [{code: 200, name: "OK", desc: "Request succeeded.", cause: "The normal case - nothing to debug here."},{code: 201, name: "Created", desc: "Request succeeded and a new resource was created.", cause: "Standard response after a successful POST that creates something."},{code: 204, name: "No Content", desc: "Request succeeded, no body to return.", cause: "Common after DELETE or an update that intentionally returns nothing."},{code: 301, name: "Moved Permanently", desc: "Resource has a new permanent URL.", cause: "A redirect that search engines/browsers will cache long-term - wrong 301 targets are painful to undo."},{code: 302, name: "Found", desc: "Resource is temporarily at a different URL.", cause: "Temporary redirect, e.g. after a login flow. Browsers won't cache this as aggressively as 301."},{code: 304, name: "Not Modified", desc: "Cached version is still valid.", cause: "Client sent an If-Modified-Since/ETag header and the server confirmed nothing changed - saves re-downloading the body."},{code: 307, name: "Temporary Redirect", desc: "Like 302, but guarantees the method (GET/POST) doesn't change on redirect.", cause: "Use this instead of 302 when redirecting a POST and you need the client to POST again, not silently switch to GET."},{code: 400, name: "Bad Request", desc: "Server couldn't parse or validate the request.", cause: "Malformed JSON, a missing required field, or a request that fails server-side validation."},{code: 401, name: "Unauthorized", desc: "Authentication is required and missing or invalid.", cause: "Misleadingly named - this means 'not authenticated,' not 'not allowed.' Check the auth token/cookie."},{code: 403, name: "Forbidden", desc: "Server understood the request but refuses to authorize it.", cause: "The user IS authenticated but doesn't have permission - a genuine permissions problem, not a login problem."},{code: 404, name: "Not Found", desc: "No resource matches the requested URL.", cause: "Typo in the path, a deleted resource, or a client-side route that doesn't have a matching server route."},{code: 405, name: "Method Not Allowed", desc: "The URL exists but doesn't support this HTTP method.", cause: "Sending a POST to a GET-only endpoint (or vice versa) - check the request method, not the URL."},{code: 408, name: "Request Timeout", desc: "Server gave up waiting for the request to finish.", cause: "Slow client connection, or a request body that stalled mid-upload."},{code: 409, name: "Conflict", desc: "Request conflicts with the current state of the resource.", cause: "Classic optimistic-locking case - two clients tried to update the same resource and lost track of each other."},{code: 410, name: "Gone", desc: "Resource existed once but is permanently gone.", cause: "Deliberate signal that this isn't coming back, unlike a 404 which just means 'not found right now.'"},{code: 413, name: "Payload Too Large", desc: "Request body exceeds the server's size limit.", cause: "Usually an upload (file, image) exceeding a server or proxy's configured max body size."},{code: 415, name: "Unsupported Media Type", desc: "Server doesn't support the request's Content-Type.", cause: "Sending JSON to an endpoint expecting form-encoded data, or vice versa - check the Content-Type header."},{code: 418, name: "I'm a Teapot", desc: "An April Fools' joke from RFC 2324 (Hyper Text Coffee Pot Control Protocol) that some real APIs still implement for fun.", cause: "Not a real error - occasionally used deliberately as an easter egg or a deliberate 'no' from an API."},{code: 422, name: "Unprocessable Entity", desc: "Request is well-formed but semantically invalid.", cause: "Valid JSON/syntax, but a field fails a business-logic rule (e.g. an email that's malformed, a date in the past where that's not allowed)."},{code: 429, name: "Too Many Requests", desc: "Client has hit a rate limit.", cause: "You're being throttled - check for a Retry-After header telling you how long to back off."},{code: 500, name: "Internal Server Error", desc: "Server hit an unhandled error.", cause: "Generic catch-all - check server logs, this code alone rarely tells you the actual cause."},{code: 501, name: "Not Implemented", desc: "Server doesn't support the functionality needed to fulfill the request.", cause: "Rare in practice - usually means an endpoint/method genuinely isn't built yet."},{code: 502, name: "Bad Gateway", desc: "A server acting as a gateway/proxy got an invalid response from an upstream server.", cause: "Your app server crashed or isn't running - the proxy (nginx, a load balancer) is reporting that upstream failure."},{code: 503, name: "Service Unavailable", desc: "Server is temporarily unable to handle the request.", cause: "Overload, maintenance mode, or a deploy in progress - usually temporary, often paired with a Retry-After header."},{code: 504, name: "Gateway Timeout", desc: "A gateway/proxy didn't get a response from upstream in time.", cause: "The upstream server is alive but too slow - a real timeout, distinct from 502's 'upstream gave a bad/no response.'"}, ];function renderHttpStatusList(){const query = document.getElementById("http-search").value.trim().toLowerCase();const list = document.getElementById("http-status-list");const matches = HTTP_STATUS_CODES.filter((s) => !query || String(s.code).includes(query) || s.name.toLowerCase().includes(query) || s.desc.toLowerCase().includes(query) || s.cause.toLowerCase().includes(query) );list.innerHTML = matches.length ? matches.map((s) => `
      <div style="border:1px solid var(--phosphor-dim); padding:0.75rem 1rem; margin-bottom:0.75rem;">
        <div style="font-size:1.1rem; color:var(--phosphor);"><strong>${s.code}</strong> ${s.name}</div>
        <div style="font-size:0.85rem; margin-top:0.35rem;">${s.desc}</div>
        <div style="font-size:0.85rem; color:var(--phosphor-dim-text); margin-top:0.35rem;">&gt; ${s.cause}</div>
      </div>
    `).join("") : `<p style="color:var(--phosphor-dim-text);">// no match</p>`;}document.addEventListener("DOMContentLoaded", renderHttpStatusList);